<?php
$active_module = 'properties'; require_once __DIR__ . '/layout.php'; require_once __DIR__ . '/../config/hotel_form.php';
$u=$supplier_user; $id=filter_input(INPUT_GET,'product',FILTER_VALIDATE_INT); if(!$id){header('Location: /nexustraveltech/tedarikci/tesisler');exit;}
$q=db()->prepare("SELECT * FROM properties WHERE id=? AND supplier_id=? AND property_type='hotel'");$q->execute([$id,$u['supplier_id']]);$hotel=$q->fetch();if(!$hotel){http_response_code(404);exit('Otel bulunamadı.');}
$locales=['en'=>'English','de'=>'Deutsch','ru'=>'Русский','ar'=>'العربية','fr'=>'Français']; $scopes=['property'=>'Genel tesis','room'=>'Oda','bathroom'=>'Banyo','activity'=>'Aktivite','event'=>'Etkinlik','kids_club'=>'Çocuk kulübü']; $error='';$notice=isset($_GET['saved'])?'Medya kaydedildi.':(isset($_GET['translated'])?'AI çevirileri kaydedildi.':'');
function translation_upsert(int $propertyId,string $entityType,int $entityId,string $locale,string $field,string $value):void{db()->prepare('INSERT INTO property_content_translations (property_id,entity_type,entity_id,locale,field_key,value,translation_source) VALUES (?,?,?,?,?,?,?) ON CONFLICT (property_id,entity_type,entity_id,locale,field_key) DO UPDATE SET value=EXCLUDED.value,translation_source=EXCLUDED.translation_source,updated_at=now()')->execute([$propertyId,$entityType,$entityId,$locale,$field,$value,'ai']);}
function ai_translate_nexus(string $text,string $locale):string{
  $settings=db_config();$key=(string)($settings['deepseek_api_key']??'');
  if($key==='')throw new RuntimeException('AI çevirisi için config/secrets.php içine deepseek_api_key eklenmelidir.');
  $language=['en'=>'English','de'=>'German','ru'=>'Russian','ar'=>'Arabic','fr'=>'French'][$locale]??$locale;
  $body=['model'=>$settings['deepseek_model']??'deepseek-chat','messages'=>[
    ['role'=>'system','content'=>'You translate tourism listing content accurately. Return only the requested translation.'],
    ['role'=>'user','content'=>"Translate the following Turkish tourism listing text into {$language}. Keep proper names, numbers, concise sales tone and HTML-free formatting.\n\n".$text]
  ],'stream'=>false,'temperature'=>0.2];
  $ch=curl_init('https://api.deepseek.com/chat/completions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($body,JSON_UNESCAPED_UNICODE),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>45]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);
  if($status<200||$status>=300||empty($data['choices'][0]['message']['content']))throw new RuntimeException('DeepSeek çevirisi tamamlanamadı.');
  return trim($data['choices'][0]['message']['content']);
}
$rooms=db()->prepare('SELECT id,name FROM room_types WHERE property_id=? ORDER BY id');$rooms->execute([$id]);$rooms=$rooms->fetchAll();
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!csrf_valid($_POST['csrf_token'] ?? null)) { $error = 'Güvenlik doğrulaması yenilendi. Lütfen tekrar deneyin.'; }
  elseif (($_POST['action'] ?? '') === 'upload_media') {
    $scope = $_POST['media_scope'] ?? 'property'; $roomId = (int)($_POST['room_type_id'] ?? 0);
    if (!in_array($scope, array_keys($scopes), true)) $error = 'Geçerli medya türü seçin.';
    if ($error === '' && in_array($scope, ['room','bathroom'], true)) { $check=db()->prepare('SELECT 1 FROM room_types WHERE id=? AND property_id=?'); $check->execute([$roomId,$id]); if (!$check->fetch()) $error='Oda veya banyo görseli için ilgili oda tipini seçin.'; }
    if (!in_array($scope, ['room','bathroom'], true)) $roomId = 0;
    $file = $_FILES['media'] ?? null; $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if ($error === '' && (!$file || $file['error'] !== UPLOAD_ERR_OK || $file['size'] > 8*1024*1024)) $error='JPG, PNG veya WEBP biçiminde en fazla 8 MB görsel yükleyin.';
    if ($error === '') { $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); if(!isset($allowed[$mime])) $error='Bu görsel biçimi desteklenmiyor.'; else { $dir=dirname(__DIR__).'/uploads/properties/'.$id; if(!is_dir($dir)) mkdir($dir,0755,true); $filename=bin2hex(random_bytes(12)).'.'.$allowed[$mime]; if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename)) $error='Görsel yüklenemedi.'; else { db()->prepare('INSERT INTO property_media (property_id,room_type_id,media_scope,file_path,file_name,mime_type,title,description,alt_text,is_cover,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$roomId?:null,$scope,'uploads/properties/'.$id.'/'.$filename,basename((string)$file['name']),$mime,trim((string)($_POST['title']??''))?:null,trim((string)($_POST['description']??''))?:null,trim((string)($_POST['alt_text']??''))?:null,false,0]); header('Location: /nexustraveltech/tedarikci/otel-icerik-medya?product='.$id.'&saved=1'); exit; } } }
  } elseif (($_POST['action'] ?? '') === 'translate_all') {
    $targets=array_values(array_intersect($_POST['locales']??[],array_keys($locales))); if(!$targets) $error='En az bir hedef dil seçin.'; else try { $details=json_decode($hotel['product_details']??'{}',true)?:[]; $items=[['property',0,'name',$hotel['name']],['property',0,'short_description',$details['short_description']??''],['property',0,'description',$details['description']??'']]; $m=db()->prepare('SELECT id,title,description,alt_text FROM property_media WHERE property_id=?');$m->execute([$id]); foreach($m->fetchAll() as $media) foreach(['title','description','alt_text'] as $field) $items[]=['media',(int)$media['id'],$field,$media[$field]??'']; foreach($targets as $locale) foreach($items as [$type,$entity,$field,$value]) if(trim((string)$value)!=='') translation_upsert($id,$type,$entity,$locale,$field,ai_translate_nexus($value,$locale)); header('Location: /nexustraveltech/tedarikci/otel-icerik-medya?product='.$id.'&translated=1'); exit; } catch(Throwable $e) { $error=$e->getMessage(); }
  }
}
$m=db()->prepare('SELECT pm.*,r.name room_name FROM property_media pm LEFT JOIN room_types r ON r.id=pm.room_type_id WHERE pm.property_id=? ORDER BY pm.media_scope,pm.id DESC');$m->execute([$id]);$media=$m->fetchAll();
supply_start(htmlspecialchars($hotel['name']).' · içerik ve görseller',$active_module); ?>
