<style>.media-panel{background:#fff;border:1px solid var(--line);border-radius:10px;padding:25px;margin:14px 0}.media-panel h2{margin:0 0 8px;font-size:20px}.media-panel p{color:var(--muted);font-size:13px;line-height:1.5}.media-form{display:grid;grid-template-columns:1fr 1fr;gap:13px}.media-form label{display:grid;gap:6px;font-size:12px;font-weight:700}.media-form input,.media-form select,.media-form textarea{border:1px solid var(--line);border-radius:6px;padding:10px;font:inherit}.media-form .wide{grid-column:1/-1}.media-form button,.ai-button{border:0;border-radius:6px;background:var(--navy);color:#fff;padding:12px 15px;font-weight:700;width:max-content}.media-groups{display:grid;gap:14px}.media-group{background:#fff;border:1px solid var(--line);border-radius:8px;padding:18px}.media-group h3{margin:0 0 12px;font-size:15px}.media-cards{display:flex;flex-wrap:wrap;gap:10px}.media-card{width:150px}.media-card img{display:block;width:150px;height:96px;object-fit:cover;border-radius:5px}.media-card b,.media-card span{display:block;font-size:11px;margin-top:5px}.media-card span{color:var(--muted)}.locale-list{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0}.locale-list label{border:1px solid var(--line);padding:8px;border-radius:5px;font-size:12px}@media(max-width:620px){.media-form{grid-template-columns:1fr}}</style>
<section class="media-panel"><h2>AI ile çoklu dil çevirisi</h2><p>Otel adı, genel açıklamalar ve tüm görsel başlık/açıklama/alt metinleri seçili dillere kaydedilir. Önce Türkçe içerikleri tamamlayın.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="translate_all"><div class="locale-list"><?php foreach($locales as $key=>$label):?><label><input type="checkbox" name="locales[]" value="<?=$key?>"> <?=htmlspecialchars($label)?></label><?php endforeach;?></div><button class="ai-button">Seçilen dillere AI ile çevir →</button></form></section>
<section class="media-panel"><h2>Görsel ekle</h2><form method="post" enctype="multipart/form-data" class="media-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="upload_media"><label>Görsel türü<select name="media_scope"><?php foreach($scopes as $key=>$label):?><option value="<?=$key?>"><?=htmlspecialchars($label)?></option><?php endforeach;?></select></label><label>Bağlı oda tipi <select name="room_type_id"><option value="">Yalnızca oda/banyo için seçin</option><?php foreach($rooms as $room):?><option value="<?= (int)$room['id']?>"><?=htmlspecialchars($room['name'])?></option><?php endforeach;?></select></label><label class="wide">Dosya<input type="file" name="media" accept="image/jpeg,image/png,image/webp" required></label><label>Türkçe başlık<input name="title" maxlength="190" placeholder="Örn. Deluxe oda yatak alanı"></label><label>Türkçe alt metin<input name="alt_text" maxlength="255" placeholder="Erişilebilirlik ve SEO açıklaması"></label><label class="wide">Türkçe açıklama<textarea name="description" rows="3" placeholder="Bu görseldeki deneyimi anlatın; AI diğer dillere çevirebilir."></textarea></label><button>Görseli kaydet →</button></form></section>
<section class="media-groups"><?php foreach($scopes as $scope=>$label):$group=array_filter($media,fn($item)=>$item['media_scope']===$scope);if(!$group)continue;?><article class="media-group"><h3><?=htmlspecialchars($label)?></h3><div class="media-cards"><?php foreach($group as $item):?><div class="media-card"><img src="/uploads/properties/<?= (int)$id ?>/<?=htmlspecialchars(basename($item['file_path']))?>" alt="<?=htmlspecialchars($item['alt_text']?:$item['title']?:$hotel['name'])?>"><b><?=htmlspecialchars($item['title']?:'Başlıksız görsel')?></b><span><?=htmlspecialchars($item['room_name']?:'Genel')?></span></div><?php endforeach;?></div></article><?php endforeach;?></section><?php supply_end(); ?>
